"""Four additional design areas. Synthetic preview only; no account or AI service."""
from html import escape as e
import json

STYLE = '''<style>
.sp-extra{padding:24px 0 48px;overflow-wrap:anywhere}.sp-extra [hidden]{display:none!important}.sp-extra .section-nav{display:flex;flex-wrap:wrap;gap:8px 20px;margin:16px 0 24px;border-bottom:1px solid var(--sp-line);padding-bottom:12px}.sp-extra .section-nav a{display:inline-flex;align-items:center;min-height:44px;text-underline-offset:4px}.sp-extra .section-nav [aria-current="page"]{font-weight:700;color:var(--sp-ink);text-decoration-thickness:2px}.sp-extra .tile{display:flex;flex-direction:column}.sp-extra .tile>a{margin-top:auto}.sp-extra [role="status"]:not(:empty){padding:12px 16px;background:var(--sp-mint);border-radius:8px;line-height:1.6}.sp-extra .reading a{display:inline-flex;align-items:center;min-height:44px}.sp-extra .guide-feature{background:var(--sp-mint)}.sp-extra h1{font-size:38px;line-height:1.2;margin:16px 0}.sp-extra h2{font-size:25px;line-height:1.3}.sp-extra p{line-height:1.65;max-width:760px}.sp-extra .muted{color:var(--sp-muted)}.sp-extra .notice{background:#fff3d6;border-left:3px solid #c19131;padding:12px 16px;font-size:14px;margin:20px 0}.sp-extra-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:24px 0}.sp-extra .tile{border:1px solid var(--sp-line);border-radius:12px;padding:24px;min-width:0}.sp-extra .tile h2,.sp-extra .tile h3{margin:0 0 12px}.sp-extra a{color:var(--sp-green)}.sp-extra .tile>a,.sp-extra .actions>a{display:inline-flex;align-items:center;min-height:44px}.sp-extra .actions{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.sp-extra button,.sp-extra input,.sp-extra select,.sp-extra input,.sp-extra select,.sp-extra textarea{font-weight:400}.sp-extra textarea{font:inherit;min-height:44px;border:1px solid var(--sp-line);border-radius:8px;padding:10px 12px;max-width:100%;box-sizing:border-box}.sp-extra button{cursor:pointer;background:#fff;color:var(--sp-ink)}.sp-extra button.primary{background:var(--sp-green);color:#fff;border-color:var(--sp-green)}.sp-extra button:disabled{cursor:not-allowed;opacity:.65}.sp-extra :focus-visible{outline:3px solid #177fc5;outline-offset:3px}.sp-extra label{display:grid;gap:8px;font-weight:600;margin:16px 0}.sp-extra form{max-width:680px}.sp-extra form>input{width:100%}.sp-extra label.check-row{display:flex;align-items:center;gap:10px;min-height:44px}.sp-extra input[type="checkbox"]{width:20px;height:20px;min-height:20px;padding:0;margin:0;accent-color:var(--sp-green)}.sp-extra input,.sp-extra select,.sp-extra textarea{font-weight:400}.sp-extra textarea{min-height:130px;resize:vertical}.sp-extra .reading{max-width:800px}.sp-extra .reading section{padding:16px 0;border-bottom:1px solid var(--sp-line)}.sp-extra .reading li{line-height:1.7;margin:8px 0}.sp-extra .answer{background:var(--sp-mint);padding:24px;border-radius:12px;margin:20px 0}.sp-extra .answer[hidden]{display:none}.sp-extra .product-mini{display:flex;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid var(--sp-line)}.sp-extra .product-mini img{width:80px;height:80px;object-fit:contain}.sp-extra .product-mini div{flex:1;min-width:0}.sp-extra .product-mini p{margin:4px 0}.sp-extra .table-wrap{overflow:auto;border:1px solid var(--sp-line);border-radius:12px;margin-top:24px}.sp-extra table{border-collapse:collapse;width:100%;min-width:580px}.sp-extra caption{text-align:left;padding:16px;font-weight:700}.sp-extra th,.sp-extra td{text-align:left;vertical-align:top;padding:16px;border-top:1px solid var(--sp-line);line-height:1.5}.sp-extra th{background:#f4f7fa}.sp-extra .compare-picks{display:grid;grid-template-columns:1fr 1fr;gap:20px}.sp-extra .empty{padding:32px;border:1px dashed var(--sp-line);border-radius:12px;text-align:center}.sp-beta-footer{display:flex;flex-wrap:wrap;gap:8px 24px;margin:16px 0}.sp-beta-footer a{min-height:44px;display:inline-flex;align-items:center;color:var(--sp-green)}@media(max-width:767px){.sp-extra h1{font-size:30px}.sp-extra h2{font-size:23px}.sp-extra-grid{grid-template-columns:1fr}.sp-extra .tile{padding:20px}.sp-extra .compare-picks{grid-template-columns:1fr;gap:0}.sp-extra table{min-width:0;table-layout:fixed;font-size:13px}.sp-extra th,.sp-extra td{padding:12px 8px;overflow-wrap:anywhere}.sp-extra thead th:first-child{width:28%}.sp-extra .product-mini{flex-wrap:wrap}.sp-extra .answer{padding:20px}.sp-extra .product-mini button{margin-left:auto}}
</style>'''

PAGES = [('merker','Merker'),('butikker','Butikker'),('om','Om SjekkPris'),('slik-fungerer-det','Slik fungerer sammenligningen'),('kontakt','Kontakt og tilbakemelding'),('personvern','Personvern'),('spor','Spør SjekkPris'),('favoritter','Favoritter'),('prisvarsler','Prisvarsler'),('konto','Min side'),('sammenlign','Sammenlign produkter')]


def build_extended_pages(out, products, args):
    from home_release import page, home_money
    from catalogue_ui import render_listing
    def write(slug, title, content, *, notice=None):
        body=STYLE+'<section class="sp-extra"><nav class="sp-breadcrumb" aria-label="Brødsmulesti"><a href="/designoversikt/">Designoversikt</a><span aria-hidden="true">›</span><span>'+e(title)+'</span></nav><h1>'+e(title)+'</h1>'
        if notice: body+='<p class="notice">'+e(notice)+'</p>'
        groups = [('om','Om SjekkPris'),('slik-fungerer-det','Slik fungerer det'),('kontakt','Kontakt'),('personvern','Personvern')] if slug in ['om','slik-fungerer-det','kontakt','personvern'] else [('konto','Min side'),('favoritter','Favoritter'),('prisvarsler','Prisvarsler'),('sammenlign','Sammenlign')] if slug in ['konto','favoritter','prisvarsler','sammenlign'] else []
        if slug.startswith('butikker/'):
            body+='<a class="sp-guide-back" href="/butikker/">← Alle butikker</a>'
        if groups:
            body+='<nav class="section-nav" aria-label="Relaterte sider">'+''.join('<a href="/'+key+'/"'+(' aria-current="page"' if key==slug else '')+'>'+label+'</a>' for key,label in groups)+'</nav>'
        body+=content+'</section>'
        target=out/slug;target.mkdir(parents=True,exist_ok=True)
        (target/'index.html').write_text(page(title+' – betadesign',body,base='/',noindex=True),encoding='utf-8')
    def tiles(items):
        return '<div class="sp-extra-grid">'+''.join('<section class="tile"><h2>'+e(title)+'</h2><p>'+e(text)+'</p><a href="'+url+'">'+e(link)+' →</a></section>' for title,text,url,link in items)+'</div>'
    def mini(p):
        return '<div class="product-mini"><img src="/assets/tv-illustration.webp" alt="" width="80" height="80"><div><a href="/p/catalogue/'+p['local_slug']+'/">'+e(p['local_name'])+'</a><p>'+e(home_money(p['lowest_item_price']))+' · eksempelpris uten frakt</p></div></div>'
    write('guider','Guider og kjøpshjelp','<p>Forstå forskjellene før du sammenligner. Her samler vi kjøpshjelp som leder videre til relevante produkter.</p><div class="sp-extra-grid"><section class="tile guide-feature"><p class="muted">TV · Eksempelguide</p><h2>Slik finner du en TV som passer deg</h2><p>Start med behov, plass og budsjett. Se hvordan egenskaper og en enkel sjekkliste hjelper deg videre.</p><a href="/guide/velg-tv/">Les eksempelguiden →</a></section><section class="tile"><h2>Utforsk TV-utvalget</h2><p>Gå rett til produkter, filtre og eksempler på prisinnsikt.</p><a href="/kategori/tv/">Sammenlign TV-er →</a></section></div><div class="reading"><h2>Om guideinnholdet</h2><p>Dette er én lesbar designguide. Flere guider vises først når innholdet er ferdig og kvalitetssikret. Kilder, faglig kontroll og oppdateringsdato skal følge dokumentasjonen.</p></div>',notice='Designforhåndsvisning med eksempelinnhold. Dette er ikke ferdige redaksjonelle anbefalinger.')
    write('merker' ,'Utforsk merker','<p>Finn et merke og sammenlign produktene. Merkenavnene i denne visningen er fiktive.</p>'+tiles([(b,f'{sum(p["local_brand"]==b for p in products)} eksempelmodeller','/merker/'+b.lower()+'/', 'Se produkter') for b in ['Nord','Fjord']]))
    for brand in ['Nord','Fjord']:
        subset=[p for p in products if p['local_brand']==brand]
        body=render_listing(subset,**args,title=brand,category=True,breadcrumbs=[('Merker','/merker/')])
        body+=STYLE+'<section class="sp-extra"><div class="tile"><h2>Om merket</h2><p>'+brand+' er et fiktivt merke i betaen. Her kan vi senere vise dokumenterte merkeopplysninger og relevante guider.</p><a href="/merker/">Se alle eksempelmerker →</a></div></section>'
        target=out/'merker'/brand.lower();target.mkdir(parents=True,exist_ok=True)
        (target/'index.html').write_text(page(brand+' – eksempelmerke',body,base='/',noindex=True),encoding='utf-8')
    write('butikker','Butikker vi sammenligner','<p>En oversikt over butikker gjør det enklere å forstå hvor tilbudene kommer fra.</p>'+tiles([('Eksempelbutikk A','Fiktiv butikk brukt i tilbudseksemplene.','/butikker/eksempel-a/','Se butikkvisning')]),notice='Designforhåndsvisning. Ingen ekte butikkavtaler eller vurderinger vises her.')
    write('butikker/eksempel-a','Eksempelbutikk A','<p>Butikksiden samler tilbud og opplysninger om den aktuelle butikken.</p>'+tiles([('Frakt og levering','Kontroller vilkårene for det konkrete tilbudet. Frakt kan variere mellom produkter.','/slik-fungerer-det/','Slik viser vi priser'),('Tilbud fra butikken','Se hvordan butikkens tilbud inngår i sammenligningen på produktsiden.','/p/catalogue/demo-tv-2/#prices','Se eksempeltilbud')])+'<div class="tile"><h2>Butikkopplysninger</h2><p>Kontaktinformasjon, organisasjonsnummer og kjøpsvilkår vises først når de er verifisert. Vi har ikke lagt inn fiktive anmeldelser eller trygghetsmerker.</p></div>',notice='Fiktiv butikk. Dette er en designmal, ikke en anbefaling.')
    write('om','Om SjekkPris','<div class="reading"><p>SjekkPris er en uavhengig prissammenligning. Vi hjelper deg å finne produkter og sammenligne butikkenes tilbud. Du handler hos butikken.</p><section><h2>Forstå før du velger</h2><p>Produkter og priser kommer først. Forklaringer og kjøpshjelp skal gjøre det lettere å forstå forskjellene.</p></section><section><h2>Hvordan tjenesten finansieres</h2><p>Vi kan motta provisjon når du handler via lenkene våre.</p><a href="/slik-fungerer-det/">Les om prissammenligningen →</a></section><section><h2>Under utvikling</h2><p>Dette området viser design med eksempeldata. Sortiment, innhold og funksjoner er ikke ferdigstilt.</p></section></div>')
    write('slik-fungerer-det','Slik fungerer sammenligningen','<div class="reading"><section><h2>1. Finn et produkt</h2><p>Søk etter produktet eller gå via en kategori. Produktkortet leder til produktets egen sammenligning.</p><a href="/kategori/tv/">Prøv TV-kategorien →</a></section><section><h2>2. Sammenlign tilbudene</h2><p>Varepris vises uten frakt som utgangspunkt. På produktsiden kan du velge å inkludere kjent frakt. Ukjent frakt regnes ikke som gratis.</p><p>Se også tilgjengeligheten og eventuelle opplysninger om når tilbudet ble oppdatert.</p></section><section><h2>3. Gå videre til butikken</h2><p>Du fullfører kjøpet hos butikken. Kontroller endelig pris, levering og vilkår før du bestiller.</p></section><section><h2>Hva dekker tallene?</h2><p>Kategoriinnsikt gjelder det oppgitte produktutvalget. Prisnivå og prisendring er forskjellige ting; beregningsgrunnlaget skal følge tallene.</p><a href="/kategori/tv/#insights-title">Se hvordan beregningsgrunnlaget vises →</a></section></div>')
    write('kontakt','Kontakt og tilbakemelding','<p>Eksempel på hvordan du kan melde fra om feil pris, produktopplysninger eller problemer med siden.</p><form id="demo-feedback"><label>Hva gjelder det?<select><option>Feil pris</option><option>Produktopplysninger</option><option>Teknisk problem</option><option>Annet</option></select></label><label>Beskrivelse<textarea required maxlength="1500" placeholder="Bruk en eksempeltekst uten personopplysninger"></textarea></label><button class="primary" type="submit">Prøv tilbakemelding</button><p role="status" id="feedback-status"></p></form><script>document.getElementById("demo-feedback").addEventListener("submit",e=>{e.preventDefault();document.getElementById("feedback-status").textContent="Eksemplet er gjennomført. Ingenting er sendt eller lagret.";});</script>',notice='Skjemaet er bare en demonstrasjon. Ikke skriv personopplysninger; meldingen sendes ikke.')
    write('personvern','Personvern','<div class="reading"><p>Dette er et utkast til sidens struktur, ikke en ferdig personvernerklæring.</p><section><h2>Hvilke opplysninger behandles?</h2><p>Før lansering må vi beskrive den faktiske behandlingen knyttet til søk, analyse, butikklenker og eventuelle brukerkontoer.</p></section><section><h2>Formål, lagring og leverandører</h2><p>Behandlingsgrunnlag, lagringstid og mottakere må bekreftes for de tjenestene som faktisk brukes.</p></section><section><h2>Dine rettigheter og kontakt</h2><p>Behandlingsansvarlig og korrekt kontaktkanal må på plass i den endelige erklæringen.</p></section></div>',notice='Kun designmal. Juridisk innhold og faktisk databehandling er ikke ferdig avklart.')
    # A deterministic UI demonstration, never represented as a live model response.
    write('spor','Spør SjekkPris','<p>Beskriv hva du ser etter, eller still et spørsmål om sammenligningen.</p><form id="demo-question"><label for="question">Hva vil du vite?</label><input id="question" required maxlength="300" placeholder="For eksempel: Vis OLED-TV-er"><div class="actions"><button class="primary" type="submit">Prøv eksempelsvar</button></div></form><div class="actions" aria-label="Eksempelspørsmål"><button data-question="oled">Vis OLED-TV-er</button><button data-question="frakt">Er frakt inkludert?</button><button data-question="sammenlign">Sammenlign to produkter</button></div><section class="answer" id="demo-answer" hidden tabindex="-1"><h2>Eksempelsvar</h2><div id="answer-body"></div></section><p id="answer-status" role="status"></p><script>'+'''const answers={oled:'<p>Her er OLED-utvalget fra betaen. Du kan også se LED-utvalget eller alle TV-ene.</p><div class="actions"><a href="/kategori/tv/oled/">OLED-TV-er</a><a href="/kategori/tv/led/">LED-TV-er</a><a href="/kategori/tv/">Alle TV-er</a></div>',frakt:'<p>Produktkortene viser varepris. På produktsiden kan du inkludere kjent frakt. Ukjent frakt regnes ikke som gratis.</p><a href="/p/catalogue/demo-tv-2/#prices">Se tilbud med fraktvalg →</a>',sammenlign:'<p>Velg selv hvilke eksempelprodukter du vil se ved siden av hverandre.</p><a href="/sammenlign/">Åpne produktsammenligning →</a>'};function showAnswer(key){const box=document.getElementById('demo-answer');document.getElementById('answer-body').innerHTML=answers[key]||'<p>Denne demoen har ikke et svar på spørsmålet. Prøv et av eksempelspørsmålene, eller bruk produktsøket.</p><a href="/search/">Søk etter produkter →</a>';box.hidden=false;box.focus();document.getElementById('answer-status').textContent='Eksempelsvar vises. Ingen AI-tjeneste er koblet til.';}document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('question').value=b.textContent;showAnswer(b.dataset.question);}));document.getElementById('demo-question').addEventListener('submit',e=>{e.preventDefault();const q=document.getElementById('question').value.toLowerCase();showAnswer(q.includes('oled')?'oled':q.includes('frakt')?'frakt':q.includes('sammenlign')?'sammenlign':'ukjent');});'''+'</script>',notice='Interaktiv designvisning med forhåndsskrevne svar. Ingen aktiv AI, og spørsmål sendes ikke til en tjeneste.')
    fav=''.join('<div data-favorite>'+mini(p)+'<button type="button" data-remove aria-label="Fjern '+e(p['local_name'])+'">Fjern fra eksempellisten</button></div>' for p in products[:2])
    write('favoritter','Favoritter','<p>Samle produkter du vil se nærmere på.</p><div id="favorite-list">'+fav+'</div><div id="favorites-empty" class="empty" hidden><h2>Listen er tom</h2><p>Finn et produkt du vil se nærmere på.</p><a href="/kategori/tv/">Utforsk produkter →</a></div><div class="actions"><button id="favorites-reset">Gjenopprett eksemplene</button><a href="/prisvarsler/">Prøv prisvarsel</a><a href="/konto/">Se Min side</a></div><p role="status" id="favorites-status"></p><script>const list=document.getElementById("favorite-list"),initial=list.innerHTML;list.addEventListener("click",e=>{const b=e.target.closest("[data-remove]");if(!b)return;b.closest("[data-favorite]").remove();document.getElementById("favorites-empty").hidden=!!list.children.length;document.getElementById("favorites-status").textContent=list.children.length+" eksempelprodukter igjen";document.getElementById("favorites-reset").focus();});document.getElementById("favorites-reset").onclick=()=>{list.innerHTML=initial;document.getElementById("favorites-empty").hidden=true;document.getElementById("favorites-status").textContent="Eksemplene er gjenopprettet.";};</script>',notice='Prøv å fjerne og gjenopprette eksempelprodukter. Listen lagres ikke mellom sidebesøk og er ikke knyttet til en konto.')
    write('prisvarsler','Prisvarsler',mini(products[0])+'<form id="demo-alert"><label>Ønsket varepris (kr)<input id="target-price" type="number" min="1" max="9999999" step="1" required inputmode="numeric" placeholder="For eksempel 9000"></label><p class="muted">Designet gjelder varepris uten frakt. Ingen varselkanal er aktiv.</p><button type="submit" class="primary">Forhåndsvis prisvarsel</button><p role="status" id="alert-status"></p></form><div class="actions"><a href="/favoritter/">Til favoritter</a></div><script>document.getElementById("demo-alert").onsubmit=e=>{e.preventDefault();const n=Number(document.getElementById("target-price").value);document.getElementById("alert-status").textContent="Eksempel: ønsket varepris "+n.toLocaleString("nb-NO")+" kr. Ingen varsling er opprettet eller sendt.";};</script>',notice='Designforhåndsvisning. Prisovervåking og utsending av varsler er ikke aktivert.')
    write('konto','Min side','<p>Et samlet sted for favoritter og prisvarsler når kontofunksjonen er tilgjengelig.</p>'+tiles([('Favoritter','Hold oversikt over produkter du vurderer.','/favoritter/','Prøv eksempellisten'),('Prisvarsler','Se hvordan du kan velge en ønsket pris.','/prisvarsler/','Prøv varselvisningen'),('Personvern','Informasjon om behandling av personopplysninger.','/personvern/','Se sidemalen')])+'<div class="tile"><h2>Innlogging</h2><p>Kontotjenesten er ikke koblet til. Vi ber derfor ikke om e-postadresse eller passord i denne demoen.</p><button disabled>Innlogging kommer senere</button></div>',notice='Dette er design for en senere funksjon. Ingen konto opprettes.')
    items=[{'name':p['local_name'],'brand':p['local_brand'],'price':home_money(p['lowest_item_price']),'url':'/p/catalogue/'+p['local_slug']+'/'} for p in products[:5]]
    options=''.join(f'<option value="{i}">{e(p["name"])}</option>' for i,p in enumerate(items))
    write('sammenlign','Sammenlign produkter','<p>Velg to eksempelprodukter. Du kan bytte ut begge kandidatene selv.</p><div class="compare-picks"><label>Første produkt<select id="compare-a">'+options+'</select></label><label>Andre produkt<select id="compare-b">'+options+'</select></label></div><label class="check-row"><input type="checkbox" id="differences"> Vis bare forskjeller</label><p role="status" id="compare-status"></p><div class="table-wrap" tabindex="0" role="region" aria-label="Produktsammenligning"><table><caption>Eksempelprodukter side om side</caption><thead><tr><th scope="col">Egenskap</th><th scope="col" id="compare-name-a"></th><th scope="col" id="compare-name-b"></th></tr></thead><tbody id="compare-body"></tbody></table></div><script>const compareItems='+json.dumps(items,ensure_ascii=False)+''';const a=document.getElementById('compare-a'),b=document.getElementById('compare-b'),diff=document.getElementById('differences');b.value='1';function compare(){const x=compareItems[a.value],y=compareItems[b.value];document.getElementById('compare-name-a').textContent=x.name;document.getElementById('compare-name-b').textContent=y.name;const body=document.getElementById('compare-body');body.replaceChildren();document.getElementById('compare-status').textContent=a.value===b.value?'Du har valgt samme produkt to ganger. Velg en annen modell for å se forskjeller.':'To eksempelprodukter valgt.';for(const [label,key] of [['Merke','brand'],['Laveste eksempelpris uten frakt','price'],['Produktside','url']]){if(diff.checked&&x[key]===y[key])continue;const tr=document.createElement('tr'),th=document.createElement('th');th.scope='row';th.textContent=label;tr.append(th);for(const item of [x,y]){const td=document.createElement('td');if(key==='url'){const link=document.createElement('a');link.href=item.url;link.textContent='Se produkt';td.append(link);}else td.textContent=item[key];tr.append(td);}body.append(tr);}}const originalCompare=compare;compare=function(){originalCompare();const body=document.getElementById('compare-body');if(!body.children.length){const row=body.insertRow();const cell=row.insertCell();cell.colSpan=3;cell.textContent='Ingen forskjeller å vise. Velg et annet produkt eller slå av «Vis bare forskjeller».';}};a.onchange=b.onchange=diff.onchange=compare;compare();'''+'</script>',notice='Designvisning med fiktive produkter. Bare tilgjengelige eksempelfelter sammenlignes; ingen automatisk vinner eller vurderingsscore.')


def add_preview_navigation(html):
    links=''.join('<a href="/'+slug+'/">'+e(label)+'</a>' for slug,label in [('guider','Guider'),('merker','Merker'),('butikker','Butikker'),('spor','Spør SjekkPris – demo'),('konto','Min side – demo')])
    html=html.replace('<nav aria-label="Hovedmeny">','<nav aria-label="Hovedmeny">'+links,1)
    footer='<nav class="sp-beta-footer" aria-label="Om tjenesten">'+''.join('<a href="/'+slug+'/">'+e(label)+'</a>' for slug,label in PAGES[2:6])+'</nav>'
    # Shared scoped footer styles on existing and new beta pages.
    html=html.replace('</head>','<style>.sp-beta-footer{display:flex;flex-wrap:wrap;gap:8px 24px;margin:16px 0}.sp-beta-footer a{min-height:44px;display:inline-flex;align-items:center;color:var(--sp-green)}</style></head>',1)
    return html.replace('<strong>SjekkPris</strong>','<strong>SjekkPris</strong>'+footer,1)
